package com.sobrenaturaldirector.planner.lifecycle;
import com.sobrenaturaldirector.planner.model.PlanStatus;
public final class PlanLifecycle {public PlanStatus transition(PlanStatus from,PlanStatus to){if(from==null||to==null)throw new IllegalArgumentException("INVALID_STATUS");if(from==PlanStatus.COMPLETE||from==PlanStatus.ABORTED)throw new IllegalStateException("TERMINAL_PLAN");if(valid(from,to))return to;throw new IllegalStateException("INVALID_TRANSITION");}private boolean valid(PlanStatus a,PlanStatus b){if(a==b)return true;if(a==PlanStatus.IDEA&&b==PlanStatus.TENTATIVE)return true;if(a==PlanStatus.TENTATIVE&&(b==PlanStatus.RESERVED||b==PlanStatus.SUSPENDED||b==PlanStatus.ABORTED))return true;if(a==PlanStatus.RESERVED&&(b==PlanStatus.PREPARED||b==PlanStatus.SUSPENDED||b==PlanStatus.ABORTED))return true;if(a==PlanStatus.PREPARED&&(b==PlanStatus.COMMITTED||b==PlanStatus.SUSPENDED||b==PlanStatus.ABORTED))return true;if(a==PlanStatus.COMMITTED&&(b==PlanStatus.ACTIVE||b==PlanStatus.SUSPENDED||b==PlanStatus.ABORTED))return true;if(a==PlanStatus.ACTIVE&&(b==PlanStatus.COMPLETE||b==PlanStatus.SUSPENDED||b==PlanStatus.ABORTED))return true;if(a==PlanStatus.SUSPENDED&&(b==PlanStatus.TENTATIVE||b==PlanStatus.ABORTED))return true;return false;}}
